arduino.setup:
Serial.begin(9600);
pinMode(${D0}, OUTPUT);
pinMode(${D1}, OUTPUT);
pinMode(${SEL}, OUTPUT);
pinMode(${OUT}, INPUT);
Serial.println("MUX 2:1 ready");

arduino.loop:
for (int i=0; i<8; i++) {
  digitalWrite(${SEL}, (i&4)?HIGH:LOW);
  digitalWrite(${D0}, (i&1)?HIGH:LOW);
  digitalWrite(${D1}, (i&2)?HIGH:LOW);
  delay(5);
  Serial.print("MUX | SEL=");
  Serial.print((i&4)?1:0);
  Serial.print(" D0=");
  Serial.print((i&1)?1:0);
  Serial.print(" D1=");
  Serial.print((i&2)?1:0);
  Serial.print(" -> ");
  Serial.println(digitalRead(${OUT}));
  delay(300);
}
